	    LOGGER.info("handling RemoveDiagnosesFromEncounterEvent " );
	
	    Encounter parentEntity = repository.findById(parentId).get();
	    Diagnosis child = registry.project( Diagnosis.class, removeFrom.getDiagnosisId());
	    
	    parentEntity.getDiagnoses().remove( child );
	
	    // ------------------------------------------
